/* cppi::eeccf48f0f6df0fc984feb485fdf68766622c4b8ac71c69cfcfbf379993c8d03 */
select distinct request_id, weight_date, strategy_alternative, investment_cell, weight
from performance.tpm_tpm_ic_atp_weights where request_id =
(select max(request_id) from performance.tpm_tpm_ic_atp_weights)
and weight_date = '2025-05-30'

/* cppi::e8de8b2b30fc25d5e63379ad029499ba9aa7f29c60a503fb0d9b1547ee2e2d90 */
select business_date as date_, security_id, 'SP500_20' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-05-30' and business_date <= date '2025-05-30' and weight_ndo>0 and id_cppib_index = 'SP500_20_GR_USD_0_0' and security_id is not null

/* cppi::93b68370e1b3c034d9a2209c8c76a7d274ced5565c1e8e222fe1b90f1ddbc663 */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-05-30' and business_date <= date '2025-05-30' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

